/** Core shared types for the site generator. */

export interface Frontmatter {
  title: string;
  date: Date | null;
  tags: string[];
  draft: boolean;
  layout?: string;
  /** Any extra user-defined frontmatter keys pass through untouched. */
  [key: string]: unknown;
}

export interface Page {
  /** Path relative to the source dir, e.g. "posts/hello.md". */
  sourcePath: string;
  /** Output path relative to the output dir, e.g. "posts/hello/index.html". */
  outputPath: string;
  /** Site-absolute URL, e.g. "/posts/hello/". */
  url: string;
  frontmatter: Frontmatter;
  /** Raw markdown body (after frontmatter). */
  body: string;
  /** Rendered HTML body. */
  html: string;
  /** First paragraph or frontmatter `description`, for feeds/listings. */
  excerpt: string;
}

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outDir: string;
  baseUrl: string;
  title: string;
  description: string;
  includeDrafts: boolean;
}

export interface BuildResult {
  pages: Page[];
  tagPages: string[];
  filesWritten: string[];
}

export const DEFAULT_CONFIG: SiteConfig = {
  sourceDir: 'content',
  templateDir: 'templates',
  outDir: 'dist-site',
  baseUrl: 'https://example.com',
  title: 'My Site',
  description: '',
  includeDrafts: false,
};

import matter from 'gray-matter';
import type { Frontmatter } from './types.js';

export interface ParsedDocument {
  frontmatter: Frontmatter;
  body: string;
}

/** Coerce a frontmatter tags value into a clean string array. */
function normalizeTags(raw: unknown): string[] {
  if (raw == null) return [];
  const list = Array.isArray(raw)
    ? raw
    : String(raw)
        .split(',')
        .map((t) => t.trim());
  return [...new Set(list.map((t) => String(t).trim()).filter(Boolean))];
}

/** Coerce a frontmatter date into a Date, or null if absent/invalid. */
function normalizeDate(raw: unknown): Date | null {
  if (raw == null) return null;
  if (raw instanceof Date) return isNaN(raw.getTime()) ? null : raw;
  const d = new Date(String(raw));
  return isNaN(d.getTime()) ? null : d;
}

/**
 * Parse a Markdown document with optional YAML frontmatter.
 * Normalizes the well-known keys (title, date, tags, draft) and passes
 * everything else through.
 */
export function parseFrontmatter(source: string, fallbackTitle = 'Untitled'): ParsedDocument {
  const { data, content } = matter(source);

  const frontmatter: Frontmatter = {
    ...data,
    title: data.title != null ? String(data.title) : fallbackTitle,
    date: normalizeDate(data.date),
    tags: normalizeTags(data.tags),
    draft: data.draft === true || data.draft === 'true',
  };
  if (typeof data.layout === 'string') frontmatter.layout = data.layout;

  return { frontmatter, body: content };
}

import { Marked } from 'marked';
import { markedHighlight } from 'marked-highlight';
import hljs from 'highlight.js';

const marked = new Marked(
  markedHighlight({
    langPrefix: 'hljs language-',
    highlight(code: string, lang: string): string {
      const language = hljs.getLanguage(lang) ? lang : 'plaintext';
      return hljs.highlight(code, { language }).value;
    },
  }),
);
marked.setOptions({ gfm: true });

/** Render Markdown to HTML with syntax-highlighted code blocks. */
export function renderMarkdown(md: string): string {
  return marked.parse(md) as string;
}

/**
 * Extract a plain-text excerpt: first non-empty paragraph, stripped of
 * markdown-ish syntax, truncated to maxLength.
 */
export function extractExcerpt(md: string, maxLength = 240): string {
  const withoutCode = md.replace(/```[\s\S]*?```/g, '');
  const firstPara =
    withoutCode
      .split(/\n\s*\n/)
      .map((p) => p.trim())
      .find((p) => p && !p.startsWith('#')) ?? '';
  const text = firstPara
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '') // images
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1') // links -> text
    .replace(/[*_`>#]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  return text.length > maxLength ? `${text.slice(0, maxLength - 1).trimEnd()}\u2026` : text;
}

import Handlebars from 'handlebars';
import { promises as fs } from 'node:fs';
import path from 'node:path';

/**
 * Template engine backed by Handlebars.
 *
 * Expected template directory shape:
 *   templates/
 *     layouts/     default.hbs, post.hbs, ...   (must render {{{content}}})
 *     partials/    header.hbs, footer.hbs, ...  (usable as {{> header}})
 *     page.hbs ... top-level templates addressable by name
 */
export class TemplateEngine {
  private hbs = Handlebars.create();
  private templates = new Map<string, Handlebars.TemplateDelegate>();
  private layouts = new Map<string, Handlebars.TemplateDelegate>();

  constructor() {
    this.registerBuiltinHelpers();
  }

  private registerBuiltinHelpers(): void {
    this.hbs.registerHelper('formatDate', (date: unknown, fmt?: unknown) => {
      if (!(date instanceof Date) || isNaN(date.getTime())) return '';
      if (fmt === 'iso') return date.toISOString();
      return date.toISOString().slice(0, 10); // YYYY-MM-DD
    });
    this.hbs.registerHelper('eq', (a: unknown, b: unknown) => a === b);
    this.hbs.registerHelper('join', (arr: unknown, sep: unknown) =>
      Array.isArray(arr) ? arr.join(typeof sep === 'string' ? sep : ', ') : '',
    );
  }

  registerHelper(name: string, fn: Handlebars.HelperDelegate): void {
    this.hbs.registerHelper(name, fn);
  }

  /** Compile a top-level template from a string (useful for tests). */
  addTemplate(name: string, source: string): void {
    this.templates.set(name, this.hbs.compile(source));
  }

  addLayout(name: string, source: string): void {
    this.layouts.set(name, this.hbs.compile(source));
  }

  addPartial(name: string, source: string): void {
    this.hbs.registerPartial(name, source);
  }

  hasTemplate(name: string): boolean {
    return this.templates.has(name);
  }

  hasLayout(name: string): boolean {
    return this.layouts.has(name);
  }

  /** Load templates, layouts and partials from a directory on disk. */
  async loadDirectory(templateDir: string): Promise<void> {
    const entries = await fs.readdir(templateDir, { withFileTypes: true });
    for (const entry of entries) {
      const full = path.join(templateDir, entry.name);
      if (entry.isDirectory() && entry.name === 'partials') {
        for (const f of await listHbs(full)) {
          this.addPartial(stem(f), await fs.readFile(path.join(full, f), 'utf8'));
        }
      } else if (entry.isDirectory() && entry.name === 'layouts') {
        for (const f of await listHbs(full)) {
          this.addLayout(stem(f), await fs.readFile(path.join(full, f), 'utf8'));
        }
      } else if (entry.isFile() && isHbs(entry.name)) {
        this.addTemplate(stem(entry.name), await fs.readFile(full, 'utf8'));
      }
    }
  }

  /** Render a named top-level template with the given context. */
  renderTemplate(name: string, context: Record<string, unknown>): string {
    const tpl = this.templates.get(name);
    if (!tpl) throw new Error(`Template not found: "${name}"`);
    return tpl(context);
  }

  /**
   * Render a page: run `templateName` (or use `content` directly if no
   * template given), then wrap the result in `layoutName` where the layout
   * receives the rendered body as {{{content}}}.
   */
  renderPage(opts: {
    layout?: string;
    template?: string;
    content?: string;
    context: Record<string, unknown>;
  }): string {
    const { layout = 'default', template, content = '', context } = opts;
    const inner = template ? this.renderTemplate(template, context) : content;
    const layoutTpl = this.layouts.get(layout);
    if (!layoutTpl) {
      if (layout === 'default') return inner; // no default layout: passthrough
      throw new Error(`Layout not found: "${layout}"`);
    }
    return layoutTpl({ ...context, content: inner });
  }
}

const isHbs = (f: string) => /\.(hbs|handlebars|html)$/.test(f);
const stem = (f: string) => f.replace(/\.(hbs|handlebars|html)$/, '');
async function listHbs(dir: string): Promise<string[]> {
  return (await fs.readdir(dir)).filter(isHbs);
}

import type { Page, SiteConfig } from './types.js';

function escapeXml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

/** Generate an RSS 2.0 feed for the given pages (newest first). */
export function generateRss(pages: Page[], config: SiteConfig, now = new Date()): string {
  const base = config.baseUrl.replace(/\/$/, '');
  const items = [...pages]
    .filter((p) => p.frontmatter.date)
    .sort((a, b) => b.frontmatter.date!.getTime() - a.frontmatter.date!.getTime())
    .map((p) => {
      const link = `${base}${p.url}`;
      return [
        '    <item>',
        `      <title>${escapeXml(p.frontmatter.title)}</title>`,
        `      <link>${escapeXml(link)}</link>`,
        `      <guid>${escapeXml(link)}</guid>`,
        `      <pubDate>${p.frontmatter.date!.toUTCString()}</pubDate>`,
        p.frontmatter.tags.length
          ? p.frontmatter.tags.map((t) => `      <category>${escapeXml(t)}</category>`).join('\n')
          : null,
        `      <description>${escapeXml(p.excerpt)}</description>`,
        '    </item>',
      ]
        .filter((l): l is string => l != null)
        .join('\n');
    });

  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<rss version="2.0">',
    '  <channel>',
    `    <title>${escapeXml(config.title)}</title>`,
    `    <link>${escapeXml(base)}</link>`,
    `    <description>${escapeXml(config.description)}</description>`,
    `    <lastBuildDate>${now.toUTCString()}</lastBuildDate>`,
    ...items,
    '  </channel>',
    '</rss>',
    '',
  ].join('\n');
}

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { parseFrontmatter } from './frontmatter.js';
import { renderMarkdown, extractExcerpt } from './markdown.js';
import { TemplateEngine } from './templates.js';
import { generateRss } from './rss.js';
import type { BuildResult, Page, SiteConfig } from './types.js';

/** Recursively list files under `dir`, returning paths relative to it. */
async function walk(dir: string, prefix = ''): Promise<string[]> {
  const out: string[] = [];
  const entries = await fs.readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) out.push(...(await walk(path.join(dir, entry.name), rel)));
    else out.push(rel);
  }
  return out;
}

/** "posts/hello.md" -> { outputPath: "posts/hello/index.html", url: "/posts/hello/" } */
export function toOutputPath(sourcePath: string): { outputPath: string; url: string } {
  const noExt = sourcePath.replace(/\.(md|markdown)$/i, '');
  if (path.basename(noExt) === 'index') {
    const dir = path.dirname(noExt);
    const base = dir === '.' ? '' : `${dir}/`;
    return { outputPath: `${base}index.html`, url: `/${base}` };
  }
  return { outputPath: `${noExt}/index.html`, url: `/${noExt}/` };
}

export function slugifyTag(tag: string): string {
  return tag
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

/** Load and parse all markdown pages from the source directory. */
export async function loadPages(config: SiteConfig): Promise<Page[]> {
  const files = (await walk(config.sourceDir)).filter((f) => /\.(md|markdown)$/i.test(f));
  const pages: Page[] = [];
  for (const rel of files) {
    const raw = await fs.readFile(path.join(config.sourceDir, rel), 'utf8');
    const fallbackTitle = path.basename(rel).replace(/\.(md|markdown)$/i, '');
    const { frontmatter, body } = parseFrontmatter(raw, fallbackTitle);
    if (frontmatter.draft && !config.includeDrafts) continue;
    const { outputPath, url } = toOutputPath(rel);
    pages.push({
      sourcePath: rel,
      outputPath,
      url,
      frontmatter,
      body,
      html: renderMarkdown(body),
      excerpt:
        typeof frontmatter.description === 'string'
          ? frontmatter.description
          : extractExcerpt(body),
    });
  }
  // Newest first; undated pages sink to the bottom, then alphabetical.
  pages.sort((a, b) => {
    const at = a.frontmatter.date?.getTime() ?? -Infinity;
    const bt = b.frontmatter.date?.getTime() ?? -Infinity;
    return bt - at || a.frontmatter.title.localeCompare(b.frontmatter.title);
  });
  return pages;
}

/** Group pages by tag. Map key is the original tag name. */
export function collectTags(pages: Page[]): Map<string, Page[]> {
  const tags = new Map<string, Page[]>();
  for (const page of pages) {
    for (const tag of page.frontmatter.tags) {
      const list = tags.get(tag) ?? [];
      list.push(page);
      tags.set(tag, list);
    }
  }
  return tags;
}

async function writeFileDeep(filePath: string, content: string): Promise<void> {
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  await fs.writeFile(filePath, content, 'utf8');
}

/** Copy non-markdown files from source dir into the output dir verbatim. */
async function copyStatic(config: SiteConfig, files: string[]): Promise<string[]> {
  const copied: string[] = [];
  for (const rel of files) {
    if (/\.(md|markdown)$/i.test(rel)) continue;
    const dest = path.join(config.outDir, rel);
    await fs.mkdir(path.dirname(dest), { recursive: true });
    await fs.copyFile(path.join(config.sourceDir, rel), dest);
    copied.push(rel);
  }
  return copied;
}

/**
 * Full site build: pages, tag index pages, RSS feed, static assets.
 * Template resolution per page: layout = frontmatter.layout ?? "default";
 * body template = "page" if present, otherwise the raw HTML flows straight
 * into the layout as {{{content}}}.
 */
export async function buildSite(config: SiteConfig): Promise<BuildResult> {
  const engine = new TemplateEngine();
  await engine.loadDirectory(config.templateDir);

  const pages = await loadPages(config);
  const tags = collectTags(pages);
  const filesWritten: string[] = [];

  const site = {
    title: config.title,
    description: config.description,
    baseUrl: config.baseUrl,
    pages,
    tags: [...tags.keys()].sort(),
  };

  for (const page of pages) {
    const context = { site, page, ...page.frontmatter, content: page.html };
    const layout = page.frontmatter.layout ?? 'default';
    const html = engine.hasTemplate('page')
      ? engine.renderPage({ layout, template: 'page', context })
      : engine.renderPage({ layout, content: page.html, context });
    await writeFileDeep(path.join(config.outDir, page.outputPath), html);
    filesWritten.push(page.outputPath);
  }

  // Tag index pages: /tags/<slug>/index.html
  const tagPages: string[] = [];
  for (const [tag, tagged] of tags) {
    const slug = slugifyTag(tag);
    const outputPath = `tags/${slug}/index.html`;
    const context = { site, tag, slug, pages: tagged, title: `Tagged: ${tag}` };
    const html = engine.hasTemplate('tag')
      ? engine.renderPage({ layout: 'default', template: 'tag', context })
      : engine.renderPage({
          layout: 'default',
          content: renderTagFallback(tag, tagged),
          context,
        });
    await writeFileDeep(path.join(config.outDir, outputPath), html);
    filesWritten.push(outputPath);
    tagPages.push(outputPath);
  }

  // RSS feed
  const rss = generateRss(pages, config);
  await writeFileDeep(path.join(config.outDir, 'feed.xml'), rss);
  filesWritten.push('feed.xml');

  // Static passthrough (images, css living beside content)
  const allFiles = await walk(config.sourceDir);
  filesWritten.push(...(await copyStatic(config, allFiles)));

  return { pages, tagPages, filesWritten };
}

function renderTagFallback(tag: string, pages: Page[]): string {
  const items = pages
    .map((p) => `<li><a href="${p.url}">${p.frontmatter.title}</a></li>`)
    .join('\n');
  return `<h1>Tagged: ${tag}</h1>\n<ul>\n${items}\n</ul>`;
}

import http from 'node:http';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import chokidar from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import { buildSite } from './build.js';
import type { SiteConfig } from './types.js';

const MIME: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json',
  '.xml': 'application/xml',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
  '.woff2': 'font/woff2',
};

/** Client-side snippet injected into every HTML page served in dev mode. */
export function reloadScript(port: number): string {
  return `<script>
(() => {
  const connect = () => {
    const ws = new WebSocket("ws://" + location.hostname + ":${port}");
    ws.onmessage = (e) => { if (e.data === "reload") location.reload(); };
    ws.onclose = () => setTimeout(connect, 1000);
  };
  connect();
})();
</script>`;
}

/** Insert the reload script before </body>, or append if absent. */
export function injectReloadScript(html: string, port: number): string {
  const script = reloadScript(port);
  const idx = html.lastIndexOf('</body>');
  return idx === -1 ? html + script : html.slice(0, idx) + script + html.slice(idx);
}

export interface DevServer {
  close: () => Promise<void>;
  port: number;
}

/**
 * Dev server: serves the output dir, rebuilds on source/template changes
 * (via chokidar), and pushes "reload" to connected WebSocket clients.
 */
export async function startDevServer(
  config: SiteConfig,
  port = 3000,
  log: (msg: string) => void = console.log,
): Promise<DevServer> {
  await buildSite(config);
  const root = path.resolve(config.outDir);

  const server = http.createServer(async (req, res) => {
    try {
      const urlPath = decodeURIComponent((req.url ?? '/').split('?')[0]);
      let filePath = path.normalize(path.join(root, urlPath));
      if (!filePath.startsWith(root)) {
        res.writeHead(403).end('Forbidden');
        return;
      }
      const stat = await fs.stat(filePath).catch(() => null);
      if (stat?.isDirectory()) filePath = path.join(filePath, 'index.html');
      let data: Buffer;
      try {
        data = await fs.readFile(filePath);
      } catch {
        res.writeHead(404, { 'Content-Type': 'text/html' });
        res.end('<h1>404 Not Found</h1>');
        return;
      }
      const ext = path.extname(filePath).toLowerCase();
      const mime = MIME[ext] ?? 'application/octet-stream';
      if (ext === '.html') {
        const html = injectReloadScript(data.toString('utf8'), port);
        res.writeHead(200, { 'Content-Type': mime });
        res.end(html);
      } else {
        res.writeHead(200, { 'Content-Type': mime });
        res.end(data);
      }
    } catch (err) {
      res.writeHead(500).end(String(err));
    }
  });

  const wss = new WebSocketServer({ server });
  const broadcast = (msg: string) => {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) client.send(msg);
    }
  };

  let rebuildTimer: NodeJS.Timeout | null = null;
  const watcher = chokidar.watch([config.sourceDir, config.templateDir], {
    ignoreInitial: true,
  });
  watcher.on('all', (event, file) => {
    if (rebuildTimer) clearTimeout(rebuildTimer);
    rebuildTimer = setTimeout(async () => {
      log(`[sprout] ${event}: ${file} — rebuilding`);
      try {
        await buildSite(config);
        broadcast('reload');
      } catch (err) {
        log(`[sprout] build failed: ${err}`);
      }
    }, 80);
  });

  await new Promise<void>((resolve) => server.listen(port, resolve));
  log(`[sprout] dev server: http://localhost:${port} (live reload enabled)`);

  return {
    port,
    close: async () => {
      await watcher.close();
      wss.close();
      await new Promise<void>((resolve, reject) =>
        server.close((e) => (e ? reject(e) : resolve())),
      );
    },
  };
}

#!/usr/bin/env node
import { buildSite } from './build.js';
import { startDevServer } from './server.js';
import { DEFAULT_CONFIG, type SiteConfig } from './types.js';

export interface CliOptions {
  command: 'build' | 'serve' | 'help';
  config: SiteConfig;
  port: number;
}

export class CliError extends Error {}

const FLAG_ALIASES: Record<string, string> = {
  '-s': '--source',
  '-t': '--templates',
  '-o': '--out',
  '-p': '--port',
  '-d': '--drafts',
  '-h': '--help',
};

/** Parse argv (without node/script prefix) into structured CLI options. */
export function parseArgs(argv: string[]): CliOptions {
  const config: SiteConfig = { ...DEFAULT_CONFIG };
  let command: CliOptions['command'] | null = null;
  let port = 3000;

  const takesValue = new Set([
    '--source',
    '--templates',
    '--out',
    '--port',
    '--base-url',
    '--title',
    '--description',
  ]);

  for (let i = 0; i < argv.length; i++) {
    let arg = argv[i];
    let inlineValue: string | undefined;
    if (arg.startsWith('--') && arg.includes('=')) {
      const eq = arg.indexOf('=');
      inlineValue = arg.slice(eq + 1);
      arg = arg.slice(0, eq);
    }
    arg = FLAG_ALIASES[arg] ?? arg;

    if (!arg.startsWith('-')) {
      if (command) throw new CliError(`Unexpected argument: "${arg}"`);
      if (arg !== 'build' && arg !== 'serve' && arg !== 'help') {
        throw new CliError(`Unknown command: "${arg}"`);
      }
      command = arg;
      continue;
    }

    if (arg === '--help') {
      command = 'help';
      continue;
    }
    if (arg === '--drafts') {
      config.includeDrafts = true;
      continue;
    }
    if (!takesValue.has(arg)) throw new CliError(`Unknown flag: "${arg}"`);

    const value = inlineValue ?? argv[++i];
    if (value == null) throw new CliError(`Flag ${arg} requires a value`);

    switch (arg) {
      case '--source':
        config.sourceDir = value;
        break;
      case '--templates':
        config.templateDir = value;
        break;
      case '--out':
        config.outDir = value;
        break;
      case '--base-url':
        config.baseUrl = value;
        break;
      case '--title':
        config.title = value;
        break;
      case '--description':
        config.description = value;
        break;
      case '--port': {
        port = Number(value);
        if (!Number.isInteger(port) || port < 1 || port > 65535) {
          throw new CliError(`Invalid port: "${value}"`);
        }
        break;
      }
    }
  }

  return { command: command ?? 'help', config, port };
}

export const HELP = `sprout — static site generator

Usage:
  sprout build [options]    Build the site once
  sprout serve [options]    Build, serve, watch, and live-reload

Options:
  -s, --source <dir>      Markdown source directory   (default: content)
  -t, --templates <dir>   Handlebars template dir     (default: templates)
  -o, --out <dir>         Output directory            (default: dist-site)
  -p, --port <n>          Dev server port             (default: 3000)
  -d, --drafts            Include draft: true pages
      --base-url <url>    Site base URL for RSS links
      --title <str>       Site title
      --description <str> Site description
  -h, --help              Show this help
`;

export async function main(argv = process.argv.slice(2)): Promise<number> {
  let options: CliOptions;
  try {
    options = parseArgs(argv);
  } catch (err) {
    if (err instanceof CliError) {
      console.error(`Error: ${err.message}\n\n${HELP}`);
      return 1;
    }
    throw err;
  }

  if (options.command === 'help') {
    console.log(HELP);
    return 0;
  }

  if (options.command === 'build') {
    const started = Date.now();
    const result = await buildSite(options.config);
    console.log(
      `[sprout] built ${result.pages.length} pages, ${result.tagPages.length} tag pages, ` +
        `feed.xml -> ${options.config.outDir} (${Date.now() - started}ms)`,
    );
    return 0;
  }

  await startDevServer(options.config, options.port);
  return 0;
}

